:root {
  --ink: #352b35;
  --ink-soft: #75636c;
  --ink-faint: #9d8990;
  --cream: #fff8ef;
  --cream-deep: #faeadc;
  --paper: #fffdfa;
  --rose: #d96f86;
  --rose-deep: #b34e68;
  --rose-soft: #f0b6c0;
  --peach: #f2b39a;
  --sage: #7f9a84;
  --sage-deep: #5f7a66;
  --gold: #c99448;
  --plum: #3c303f;
  --plum-soft: #5d4b5d;
  --line: rgba(69, 45, 55, 0.12);
  --shadow: 0 30px 70px -46px rgba(67, 39, 51, 0.52);
  --font-display: 'Fraunces', 'Iowan Old Style', 'Palatino Linotype', Georgia, serif;
  --font-body: 'Nunito Sans', 'Avenir Next', 'Segoe UI', sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--font-body);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  min-height: 100vh;
  overflow-x: hidden;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  border: 0;
  background: none;
}

button:disabled {
  cursor: not-allowed;
}

h1,
h2,
h3,
h4,
p {
  margin: 0;
}

svg {
  display: block;
}

[hidden] {
  display: none !important;
}

::selection {
  background: var(--rose);
  color: white;
}

.screen {
  min-height: 100vh;
  position: relative;
  overflow: hidden;
}

.grain {
  position: fixed;
  inset: 0;
  z-index: 90;
  pointer-events: none;
  opacity: 0.12;
  mix-blend-mode: multiply;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E");
}

.petal-layer {
  position: fixed;
  inset: 0;
  z-index: 32;
  pointer-events: none;
  overflow: hidden;
}

.petal {
  position: absolute;
  top: -30px;
  width: 11px;
  height: 16px;
  border-radius: 70% 20% 60% 30%;
  background: linear-gradient(140deg, #ffdce2, #ee9cab);
  opacity: 0.75;
  animation: petalFall linear infinite;
  filter: drop-shadow(0 2px 2px rgba(110, 57, 76, 0.12));
}

@keyframes petalFall {
  0% {
    transform: translate3d(0, -5vh, 0) rotate(0deg);
  }
  50% {
    transform: translate3d(6vw, 52vh, 0) rotate(210deg);
  }
  100% {
    transform: translate3d(-2vw, 108vh, 0) rotate(480deg);
  }
}

.icon {
  width: 20px;
  height: 20px;
  flex: 0 0 auto;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--rose-deep);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.eyebrow span {
  width: 28px;
  height: 1px;
  background: currentColor;
  opacity: 0.55;
}

.primary-button,
.secondary-button,
.ghost-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border-radius: 999px;
  font-weight: 700;
  transition: transform 180ms ease, background 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
}

.primary-button {
  background: var(--plum);
  color: #fff8f1;
  box-shadow: 0 16px 28px -20px rgba(52, 38, 52, 0.9);
}

.primary-button:hover {
  transform: translateY(-2px);
  background: #4b3b4e;
  box-shadow: 0 20px 34px -22px rgba(52, 38, 52, 0.9);
}

.primary-button.large,
.secondary-button.large {
  min-height: 58px;
  padding: 0 24px;
  font-size: 0.95rem;
}

.primary-button svg,
.secondary-button svg {
  width: 22px;
  height: 22px;
}

.secondary-button {
  background: rgba(255, 255, 255, 0.66);
  border: 1px solid rgba(111, 73, 83, 0.16);
  color: var(--ink);
  backdrop-filter: blur(8px);
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  line-height: 1.1;
}

.secondary-button small {
  font-size: 0.67rem;
  color: var(--ink-faint);
  font-weight: 600;
}

.secondary-button:hover:not(:disabled) {
  transform: translateY(-2px);
  background: white;
  border-color: rgba(179, 78, 104, 0.3);
}

.secondary-button:disabled {
  opacity: 0.48;
}

.ghost-button {
  min-height: 40px;
  padding: 0 17px;
  color: var(--ink-soft);
  font-size: 0.78rem;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.3);
}

.ghost-button:hover {
  color: var(--rose-deep);
  border-color: rgba(179, 78, 104, 0.28);
  background: rgba(255, 255, 255, 0.6);
}

.ghost-button.light {
  color: #f9eee8;
  border-color: rgba(255, 255, 255, 0.22);
  background: rgba(255, 255, 255, 0.08);
}

.ghost-button.light:hover {
  color: white;
  border-color: rgba(255, 255, 255, 0.44);
  background: rgba(255, 255, 255, 0.14);
}

/* ---------------------------------------------------------------- Title */
.title-screen {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background:
    radial-gradient(circle at 68% 18%, rgba(255, 244, 219, 0.95), transparent 32%),
    radial-gradient(circle at 13% 9%, rgba(245, 196, 183, 0.5), transparent 35%),
    linear-gradient(160deg, #fff8ed 0%, #fbeadc 48%, #f5d9cc 100%);
}

.title-sky {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}

.sun-disc {
  position: absolute;
  width: 44vw;
  height: 44vw;
  max-width: 630px;
  max-height: 630px;
  right: 6vw;
  top: -8vw;
  border-radius: 50%;
  background: radial-gradient(circle at 42% 40%, #fff8dc 0%, #f8dcc4 47%, rgba(247, 213, 193, 0) 72%);
  filter: blur(2px);
}

.cloud {
  position: absolute;
  height: 50px;
  border-radius: 999px;
  background: rgba(255, 251, 240, 0.72);
