  height: 38px;
  opacity: 0.55;
  animation: drift 23s ease-in-out infinite alternate;
}

@keyframes drift {
  from { transform: translateX(-20px); }
  to { transform: translateX(50px); }
}

.title-hills {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 42vh;
  opacity: 0.9;
}

.title-town {
  position: absolute;
  bottom: 4.3vh;
  left: 8%;
  width: min(760px, 58vw);
  opacity: 0.36;
}

.blossom-branch {
  position: absolute;
  right: -110px;
  top: -70px;
  width: min(820px, 56vw);
  opacity: 0.95;
  transform: rotate(-4deg);
}

.title-topbar {
  position: relative;
  z-index: 4;
  display: flex;
  align-items: center;
  justify-content: space-between;
