}

.title-portrait-card {
  position: absolute;
  bottom: 0;
  width: clamp(160px, 19vw, 275px);
  aspect-ratio: 0.66;
  border-radius: 48% 48% 24px 24px / 31% 31% 24px 24px;
  background:
    radial-gradient(circle at 50% 22%, rgba(255, 249, 232, 0.92), transparent 38%),
    linear-gradient(160deg, #e9b9ad, #c9878d 55%, #785868);
