  border-radius: 999px;
  background: rgba(60, 44, 54, 0.56);
  color: #fff9f1;
  font-family: var(--font-display);
  font-size: 0.9rem;
  letter-spacing: 0.03em;
  backdrop-filter: blur(8px);
}

.title-portrait-1 {
  left: 2%;
  z-index: 2;
  transform: rotate(-7deg);
  animation-delay: -1.3s;
}

.title-portrait-2 {
  left: 33%;
  z-index: 3;
  bottom: 18px;
  width: clamp(180px, 21vw, 304px);
  background:
    radial-gradient(circle at 50% 22%, rgba(255, 250, 232, 0.95), transparent 38%),
    linear-gradient(160deg, #c8d8bf, #83a48b 55%, #4f6d5c);
