}

.title-portrait-3 {
  right: 0;
  z-index: 1;
  transform: rotate(9deg);
  background:
    radial-gradient(circle at 50% 22%, rgba(255, 250, 232, 0.95), transparent 38%),
    linear-gradient(160deg, #bed5de, #7699a8 55%, #476776);
