.footer-note {
  color: #a38a8b;
}

/* -------------------------------------------------------------- Creator */
.creator-screen {
  min-height: 100vh;
  background:
    radial-gradient(circle at 10% 10%, rgba(242, 181, 166, 0.34), transparent 32%),
    radial-gradient(circle at 94% 16%, rgba(178, 202, 178, 0.34), transparent 32%),
    linear-gradient(145deg, #fffaf2, #f8e9dd);
  padding-bottom: 36px;
}

.creator-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 22px 5vw;
  position: relative;
  z-index: 3;
}

.creator-progress {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.66rem;
  letter-spacing: 0.1em;
  color: #b09a9d;
  text-transform: uppercase;
}

.creator-progress span {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 1px solid rgba(110, 77, 85, 0.2);
}

.creator-progress span.active {
