const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const assert = require('node:assert');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', (error) => errors.push(`pageerror: ${error.message}`));
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(`console: ${msg.text()}`); });
  const base = 'http://localhost:3002';
  await page.goto(base, { waitUntil: 'networkidle' });

  // Fresh story
  await page.click('#new-game-button');
  await page.fill('#player-name', 'Test');
  await page.click('[data-action="creator-hair-style"][data-id="pony"]');
  await page.click('#start-story-button');
  await page.locator('#modal-root.has-modal').waitFor();
  await page.click('[data-action="close-modal"]');
  await page.waitForTimeout(300);
  assert.equal(await page.locator('.location-card').count(), 6, 'six location cards');
  assert.equal(await page.locator('.town-hero').count(), 1, 'town hero');

  // Work
  const coinsBefore = await page.evaluate(() => JSON.parse(localStorage.getItem('hanami-hearts-save-v1')).coins);
  await page.click('[data-action="work-shift"]');
  await page.waitForTimeout(100);
  const coinsAfter = await page.evaluate(() => JSON.parse(localStorage.getItem('hanami-hearts-save-v1')).coins);
  assert.ok(coinsAfter > coinsBefore, 'work earns coins');

  // Chat and gift
  await page.click('[data-action="open-character"][data-char="aiko"]');
  await page.click('[data-action="interact"][data-kind="chat"]');
  await page.waitForTimeout(100);
  await page.click('[data-action="gift-mode"]');
  await page.click('[data-action="give-gift"][data-gift="tart"]');
  await page.waitForTimeout(100);
  let saved = await page.evaluate(() => JSON.parse(localStorage.getItem('hanami-hearts-save-v1')));
  assert.equal(saved.rels.aiko.affection, 29, 'chat + favourite gift');
  assert.equal(saved.rels.aiko.gifts, 1, 'gift counted');

  // Date (needs 30; one more chat)
  await page.click('[data-action="interact"][data-kind="chat"]');
  await page.waitForTimeout(100);
  await page.click('[data-action="date-mode"]');
  await page.locator('[data-action="date-choice"]').first().click();
  await page.waitForTimeout(150);
  saved = await page.evaluate(() => JSON.parse(localStorage.getItem('hanami-hearts-save-v1')));
  assert.equal(saved.rels.aiko.dates, 1, 'date counted');
  assert.ok(saved.rels.aiko.affection >= 54, 'date affection applied');
  await page.locator('[data-action="back-to-character"]').click();
  await page.click('[data-action="close-modal"]');

  // End day
  await page.click('[data-action="end-day"]');
  await page.locator('[data-action="close-modal"]').click();
  saved = await page.evaluate(() => JSON.parse(localStorage.getItem('hanami-hearts-save-v1')));
  assert.equal(saved.day, 2, 'day advances');
  assert.equal(saved.energy, 100, 'energy restored');

  // Inject near-marriage state and reload
  saved.rels.aiko.affection = 85;
  saved.rels.aiko.status = 'dating';
  saved.coins = 2000;
  saved.energy = 100;
  await page.evaluate((state) => localStorage.setItem('hanami-hearts-save-v1', JSON.stringify(state)), saved);
  await page.reload({ waitUntil: 'networkidle' });
  await page.click('#continue-button');
  await page.waitForTimeout(300);
  await page.click('[data-action="open-character"][data-char="aiko"]');
  await page.click('[data-action="propose"]');
  await page.waitForTimeout(200);
  assert.ok(await page.locator('.ceremony').count(), 'proposal ceremony');
  await page.click('[data-action="close-ceremony"]');
  await page.click('[data-action="open-character"][data-char="aiko"]');
  await page.click('[data-action="marry"]');
  await page.waitForTimeout(200);
  assert.ok((await page.locator('.ceremony h3').innerText()).includes('Just married'), 'wedding ceremony');
  await page.click('[data-action="close-ceremony"]');
  saved = await page.evaluate(() => JSON.parse(localStorage.getItem('hanami-hearts-save-v1')));
  assert.equal(saved.rels.aiko.status, 'married', 'married status');
  assert.equal(saved.coins, 1600, 'wedding costs');

  // Home, family
  await page.click('[data-action="go-view"][data-view="home"]');
  await page.waitForTimeout(150);
  await page.locator('[data-action="family-modal"]').first().click();
  await page.waitForTimeout(120);
  await page.locator('[data-action="have-child"]').first().click();
  await page.waitForTimeout(200);
  assert.ok((await page.locator('.ceremony h3').innerText()).includes('new chapter'), 'baby ceremony');
  await page.click('[data-action="close-ceremony"]');
  saved = await page.evaluate(() => JSON.parse(localStorage.getItem('hanami-hearts-save-v1')));
  assert.equal(saved.children.length, 1, 'child added');
  const childId = saved.children[0].id;

  // Raise three times
  for (let i = 0; i < 3; i += 1) {
    await page.locator(`[data-action="raise-child"][data-child="${childId}"]`).click();
    await page.waitForTimeout(80);
  }
  saved = await page.evaluate(() => JSON.parse(localStorage.getItem('hanami-hearts-save-v1')));
  assert.equal(saved.children[0].stage, 3, 'child grown');
  await page.locator(`[data-action="toggle-child-work"][data-child="${childId}"]`).click();
  await page.waitForTimeout(100);
  saved = await page.evaluate(() => JSON.parse(localStorage.getItem('hanami-hearts-save-v1')));
  assert.equal(saved.children[0].working, true, 'grown child working');

  // Hearts and ledger
  await page.click('[data-action="go-view"][data-view="hearts"]');
  await page.waitForTimeout(120);
  assert.equal(await page.locator('.heart-card').count(), 6, 'six hearts');
  await page.click('[data-action="go-view"][data-view="ledger"]');
  await page.waitForTimeout(120);
  assert.equal(await page.locator('.log-entry').count() > 0, true, 'log entries');

  await page.screenshot({ path: 'screenshots/test-ledger.png', fullPage: false });

  // Rest income includes grown working child
  await page.click('[data-action="end-day"]');
  await page.locator('[data-action="close-modal"]').click();
  saved = await page.evaluate(() => JSON.parse(localStorage.getItem('hanami-hearts-save-v1')));
  assert.ok(saved.coins > 0, 'coins exist');

  console.log('FUNCTIONAL_OK');
  console.log(JSON.stringify({ errors, day: saved.day, coins: saved.coins, childStage: saved.children[0].stage, achievements: saved.achievements }, null, 2));
  await browser.close();
})().catch(async (error) => {
  console.error('TEST_FAILED', error);
  process.exit(1);
});

