const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('node:fs');
const path = require('node:path');

const BASE = 'http://localhost:3002';
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots/final';

const player = {
  name: 'Haru',
  pronoun: 'they',
  skin: { id: 'peach', color: '#f2c6a5', shade: '#dda27e' },
  hairStyle: 'wavy',
  hairColor: { id: 'ink', color: '#35292f', shade: '#211a1f' },
  eyeColor: '#5c7a66',
  outfitColor: { id: 'sage', color: '#7d9b8a', dark: '#5c7a69' },
  accessory: 'earrings',
  body: 'soft',
};

const rel = (affection, status, dates, gifts) => ({ affection, status, dates, gifts, lastLine: 0, metDay: 2 });

const save = {
  version: 1,
  player,
  day: 24,
  phaseActions: 0,
  actionsToday: 0,
  energy: 90,
  maxEnergy: 100,
  coins: 3260,
  rels: {
    aiko: rel(92, 'dating', 4, 5),
    mei: rel(100, 'married', 5, 7),
    rin: rel(100, 'married', 4, 6),
    yuna: rel(100, 'married', 6, 8),
    hana: rel(56, 'single', 1, 2),
    sora: rel(34, 'single', 1, 0),
  },
  children: [
    { id: 'child-1', name: 'Sora', parentId: 'mei', stage: 3, working: true, bornDay: 4, skin: { id: 'porcelain', color: '#f8dcc6', shade: '#e8bda5' }, hair: { color: '#3d3450', shade: '#292238' }, hairStyle: 'hime', eye: '#725c9b', accent: '#66527e', outfit: '#a8c0b0' },
    { id: 'child-2', name: 'Hina', parentId: 'rin', stage: 3, working: true, bornDay: 7, skin: { id: 'honey', color: '#dda27e', shade: '#c4845f' }, hair: { color: '#b1683f', shade: '#874728' }, hairStyle: 'braids', eye: '#5f8a5c', accent: '#d59c52', outfit: '#e7b6a5' },
    { id: 'child-3', name: 'Kaito', parentId: 'yuna', stage: 2, working: false, bornDay: 11, skin: { id: 'umber', color: '#8d5a3f', shade: '#70432f' }, hair: { color: '#241f29', shade: '#151118' }, hairStyle: 'pony', eye: '#97608f', accent: '#d96f86', outfit: '#a8bfd0' },
    { id: 'child-4', name: 'Nao', parentId: 'mei', stage: 0, working: false, bornDay: 19, skin: { id: 'porcelain', color: '#f8dcc6', shade: '#e8bda5' }, hair: { color: '#3d3450', shade: '#292238' }, hairStyle: 'bob', eye: '#725c9b', accent: '#66527e', outfit: '#d8c1e0' },
  ],
  log: [
    { day: 24, text: 'Hina chose to join the family business at the bakery counter.', icon: 'work' },
    { day: 24, text: 'Aiko left a note under your coffee: "Come home before the moon gets too high."', icon: 'heart' },
    { day: 23, text: 'The household earned 196 coins overnight.', icon: 'coin' },
    { day: 22, text: 'Mei read aloud by the window until the lamp burned low.', icon: 'family' },
  ],
  achievements: ['first-hello', 'first-date', 'first-marriage', 'first-child', 'first-grown', 'family-business'],
  stats: { gifts: 28, dates: 21, shifts: 34 },
  totalEarned: 14820,
  completed: false,
  seenIntro: true,
  settings: { sound: false },
  createdAt: Date.now(),
};

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const browser = await chromium.launch({ headless: true });
  const errors = [];
  const seed = async (page) => {
    await page.addInitScript((data) => {
      localStorage.setItem('hanami-hearts-save-v1', JSON.stringify(data));
    }, save);
    page.on('pageerror', (e) => errors.push(e.message));
    page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  };

  // Title, fresh
  const titlePage = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await titlePage.goto(BASE, { waitUntil: 'networkidle' });
  await titlePage.waitForFunction(() => document.fonts.status === 'loaded');
  await titlePage.screenshot({ path: path.join(OUT, 'desktop-title.png') });
  await titlePage.close();

  const shoot = async (page, name) => {
    await page.waitForTimeout(350);
    await page.screenshot({ path: path.join(OUT, `${name}.png`), animations: 'disabled' });
    console.log('shot', name);
  };

  // Desktop game views
  const desktop = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await seed(desktop);
  await desktop.goto(BASE, { waitUntil: 'networkidle' });
  await desktop.click('#continue-button');
  await desktop.waitForTimeout(500);
  await shoot(desktop, 'desktop-town');

  await desktop.click('[data-action="go-view"][data-view="hearts"]');
  await shoot(desktop, 'desktop-hearts');

  await desktop.click('[data-action="go-view"][data-view="home"]');
  await shoot(desktop, 'desktop-home');

  await desktop.click('[data-action="go-view"][data-view="ledger"]');
  await shoot(desktop, 'desktop-ledger');

  await desktop.click('[data-action="go-view"][data-view="town"]');
  await desktop.click('[data-action="open-character"][data-char="aiko"]');
  await desktop.locator('#modal-root.has-modal').waitFor();
  await shoot(desktop, 'desktop-character');

  await desktop.click('[data-action="gift-mode"]');
  await shoot(desktop, 'desktop-gifts');
  await desktop.click('[data-action="close-modal"]');
  await desktop.waitForTimeout(250);

  await desktop.click('[data-action="open-character"][data-char="mei"]');
  await desktop.locator('#modal-root.has-modal').waitFor();
  await shoot(desktop, 'desktop-character-mei');
  await desktop.click('[data-action="close-modal"]');
  await desktop.waitForTimeout(250);

  // Proposal ceremony
  await desktop.click('[data-action="open-character"][data-char="aiko"]');
  await desktop.locator('#modal-root.has-modal').waitFor();
  await desktop.click('[data-action="propose"]');
  await desktop.waitForTimeout(500);
  await shoot(desktop, 'desktop-ceremony');
  await desktop.click('[data-action="close-ceremony"]');
  await desktop.waitForTimeout(300);

  // Menu
  await desktop.click('[data-action="open-menu"]');
  await desktop.waitForTimeout(300);
  await shoot(desktop, 'desktop-menu');
  await desktop.click('[data-action="close-modal"]');
  await desktop.waitForTimeout(250);

  // Family modal
  await desktop.click('[data-action="go-view"][data-view="home"]');
  await desktop.click('[data-action="family-modal"]');
  await desktop.waitForTimeout(300);
  await shoot(desktop, 'desktop-family');
  await desktop.close();

  // Mobile
  const phone = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  await seed(phone);
  await phone.goto(BASE, { waitUntil: 'networkidle' });
  await phone.click('#continue-button');
  await phone.waitForTimeout(500);
  await shoot(phone, 'mobile-town');

  await phone.click('[data-action="go-view"][data-view="hearts"]');
  await shoot(phone, 'mobile-hearts');

  await phone.click('[data-action="go-view"][data-view="home"]');
  await shoot(phone, 'mobile-home');

  await phone.click('[data-action="go-view"][data-view="ledger"]');
  await shoot(phone, 'mobile-ledger');

  await phone.click('[data-action="go-view"][data-view="town"]');
  await phone.click('[data-action="open-character"][data-char="aiko"]');
  await phone.locator('#modal-root.has-modal').waitFor();
  await shoot(phone, 'mobile-character');
  await phone.close();

  console.log(errors.length ? `ERRORS: ${JSON.stringify(errors)}` : 'CAPTURE_OK');
  await browser.close();
})();

